import{_ as r,o as l,c as e,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2020-07-27","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2020-07-27","date":"2020-07-27T00:00:00.000Z","updated":"2020-07-28T00:00:00.000Z","tags":["Ceph","Orchestrator","Rook","Distributed Storage","Bug Fixes"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-07-27.md","filePath":"posts/2020/Ceph_Orchestrator_Meeting_2020-07-27.md","lastUpdated":1780459816000}'),o={name:"posts/2020/Ceph_Orchestrator_Meeting_2020-07-27.md"};function s(p,t,n,a,g,_){return l(),e("div",null,[...t[0]||(t[0]=[i("<p>本次会议纪要主要围绕Ceph Orchestrator的更新和维护展开，以下为会议的关键点：</p><p><strong>会议概要</strong></p><ul><li>会议主题：Ceph Orchestrator会议</li><li>参会人员：团队成员</li><li>会议日期：2020年7月27日</li></ul><p><strong>主要议题与讨论内容</strong></p><ol><li><p><strong>Bug修复与性能提升</strong>：</p><ul><li>上周修复了多项小bug，并实现了OSD创建速度的大幅提升，现在可以并行在至少10个主机上同时执行，速度提升约10倍。</li></ul></li><li><p><strong>文档更新与代码审查</strong>：</p><ul><li>Karen Kevin提交了几个针对fadm文档的上游PR，请求团队成员进行审查。</li><li>确认了GitHub用户名的正确性，以便后续的代码审查工作。</li></ul></li><li><p><strong>Rook 1.4版本准备</strong>：</p><ul><li>正在为Rook 1.4版本做准备，等待CSI 3.0版本的发布，该版本今日已发布。</li><li>计划下周创建分支并发布Rook 1.4版本。</li></ul></li><li><p><strong>Orchestrator设计哲学讨论</strong>：</p><ul><li>讨论了Orchestrator在处理demon失败时的行为和设计理念。</li><li>目前Orchestrator在demon失败后不会自动重新调度，依赖于systemd进行重启。</li><li>讨论了是否应该增加自动重新调度的功能，以及这可能带来的复杂性。</li></ul></li><li><p><strong>文档与安装指南更新</strong>：</p><ul><li>讨论了即将推出的Crisp安装指南的更新，该指南将被拆分为多个小PR以便审查。</li><li>寻求图形设计方面的帮助，特别是按钮设计。</li></ul></li></ol><p><strong>决定事项</strong></p><ul><li>确认了GitHub用户名的正确性，以便进行代码审查。</li><li>确定了Rook 1.4版本的发布计划。</li><li>讨论了Orchestrator在处理demon失败时的行为，但未做出具体决定。</li></ul><p><strong>后续行动计划</strong></p><ul><li>继续进行Rook 1.4版本的准备工作。</li><li>提交并审查Crisp安装指南的多个PR。</li><li>寻求图形设计方面的帮助，以改进文档的视觉效果。</li></ul><p><strong>其他事项</strong></p><ul><li>无其他重要事项。</li></ul><p><strong>会议总结</strong> 本次会议在高效和快速的节奏中结束，团队成员对Ceph Orchestrator的更新和维护进行了深入讨论，并制定了后续的行动计划。</p>",12)])])}const h=r(o,[["render",s]]);export{c as __pageData,h as default};
